<?php foreach($exams as $exam): ?><tr><td><div class="exam-title"><?php echo htmlspecialchars($exam['title']); ?></div><div class="exam-subtitle">Entrance · <?php echo htmlspecialchars($exam['subject_name']); ?></div></td><td><?php echo htmlspecialchars($exam['class_name'].' / '.$exam['subject_name']); ?></td><td><span class="fw-semibold"><?php echo (int)$exam['candidate_count']; ?></span></td><td><?php echo (int)$exam['question_count']; ?></td><td><span class="exam-state <?php echo $exam['is_published']?'live':''; ?>"><i class="fas fa-circle" style="font-size:.45rem"></i><?php echo $exam['is_published']?'Published':'Draft'; ?></span></td><td class="d-flex flex-wrap gap-2"><a class="btn btn-sm btn-primary" href="question_management.php?exam_id=<?php echo (int)$exam['exam_id']; ?>&class_id=<?php echo (int)$exam['class_id']; ?>&subject_id=<?php echo (int)$exam['subject_id']; ?>"><i class="fas fa-pen me-1"></i>Questions</a><a class="btn btn-sm btn-outline-info" href="entrance_exam_results.php?exam_id=<?php echo (int)$exam['exam_id']; ?>"><i class="fas fa-chart-bar me-1"></i>Results</a></td></tr><?php endforeach; ?>
<?php if(!$exams): ?><tr><td colspan="6" class="text-muted">No entrance exams assigned to you.</td></tr><?php endif; ?></tbody></table></div></div></div>
